'use strict';
(()=>{
 const dialog=document.getElementById('context-dialog');if(!dialog)return;
 const el=id=>document.getElementById(id),fmt=n=>Number(n).toLocaleString('de-DE',{maximumSignificantDigits:7}),stamp=t=>new Date(t).toISOString().slice(0,16).replace('T',' ')+' UTC',H=3600000,Q=900000,DAY=86400000;
 let generation=0,controller=null,timer=null,symbol='',button=null;
 function parse(json,duration){if(json.code!=='00000'||!Array.isArray(json.data)||!Number.isFinite(+json.requestTime))throw Error('Keine gültigen Daten');const now=+json.requestTime,found=new Map();for(const row of json.data){const [t,o,h,l,c]=row.map(Number);if(![t,o,h,l,c].every(Number.isFinite)||t%duration||t+duration>now||l<=0||o<=0||c<=0||h<Math.max(o,c)||l>Math.min(o,c))continue;found.set(t,[t,o,h,l,c])}return {now,rows:[...found.values()].sort((a,b)=>a[0]-b[0])}}
 function contiguous(rows,start,count,step){const by=new Map(rows.map(c=>[c[0],c]));const result=Array.from({length:count},(_,i)=>by.get(start+i*step));return result.every(Boolean)?result:null}
 function ema(values,n){let x=values.slice(0,n).reduce((a,b)=>a+b,0)/n;for(const v of values.slice(n))x+=(v-x)*2/(n+1);return x}
 function trend(parsed){const end=Math.floor(parsed.now/H)*H,rows=parsed.rows.filter(c=>c[0]+H<=end);let seq=[];for(let i=rows.length-1;i>=0;i--){if(seq.length&&rows[i][0]+H!==seq[0][0])break;seq.unshift(rows[i])}if(seq.length<100||seq.at(-1)[0]+H!==end)return null;const closes=seq.map(c=>c[4]),fast=ema(closes,20),slow=ema(closes,50),diff=(fast/slow-1)*100;return {fast,slow,diff,label:diff>=.1?'↑ Aufwärts':diff<=-.1?'↓ Abwärts':'↔ Uneinheitlich',end,count:seq.length}}
 function zones(hour,quarter){const day=hour?Math.floor(hour.now/DAY)*DAY-DAY:0,prior=hour?contiguous(hour.rows,day,24,H):null,end=quarter?Math.floor(quarter.now/Q)*Q:0,recent=quarter?contiguous(quarter.rows,end-96*Q,96,Q):null;return {prior:prior?{high:Math.max(...prior.map(c=>c[2])),low:Math.min(...prior.map(c=>c[3])),start:day,end:day+DAY}:null,recent:recent?{high:Math.max(...recent.map(c=>c[2])),low:Math.min(...recent.map(c=>c[3])),start:end-96*Q,end}:null,reference:recent?recent.at(-1)[4]:null}}
 function level(p,ref){if(!Number.isFinite(p))return '—';const d=ref>0?(p/ref-1)*100:NaN;return fmt(p)+' USDT'+(Number.isFinite(d)?' · '+(d>=0?'+':'')+d.toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2})+' %':'')}
 function show(t,z){const trendNode=el('context-trend');trendNode.textContent=t?t.label:'Nicht verfügbar';el('context-trend-detail').textContent=t?`EMA 20 ${fmt(t.fast)} · EMA 50 ${fmt(t.slow)} · Abstand ${t.diff.toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2})} % · ${t.count} abgeschlossene 1h-Kerzen · bis ${stamp(t.end)}`:'Zu wenige lückenlose oder keine aktuellen 1h-Kerzen.';const ref=z?.reference;for(const [id,obj,key] of [['context-day-high',z?.prior,'high'],['context-day-low',z?.prior,'low'],['context-24-high',z?.recent,'high'],['context-24-low',z?.recent,'low']])el(id).textContent=obj?level(obj[key],ref):'Nicht verfügbar';el('context-day-time').textContent=z?.prior?`${stamp(z.prior.start)} bis ${stamp(z.prior.end)}`:'Vortag: Daten unvollständig';el('context-24-time').textContent=z?.recent?`${stamp(z.recent.start)} bis ${stamp(z.recent.end)}`:'24h: Daten unvollständig';el('context-reference').textContent=ref?`Abstand zum letzten abgeschlossenen 15m-Schluss: ${fmt(ref)} USDT · ${stamp(z.recent.end)}`:'Abstände nicht verfügbar';}
 async function load(token){if(!symbol||token!==generation)return;const cur=symbol;const ac=new AbortController();controller=ac;const signal=ac.signal,timeout=setTimeout(()=>ac.abort(),12000);async function request(gran,limit,duration){const url='https://api.bitget.com/api/v2/mix/market/candles?symbol='+encodeURIComponent(cur)+'&productType=USDT-FUTURES&granularity='+gran+'&kLineType=market&limit='+limit;const res=await fetch(url,{signal,cache:'no-store'});if(!res.ok)throw Error('HTTP '+res.status);return parse(await res.json(),duration)}try{const [h,q]=await Promise.allSettled([request('1H',200,H),request('15m',100,Q)]);if(token!==generation)return;const hour=h.status==='fulfilled'?h.value:null,quarter=q.status==='fulfilled'?q.value:null;const t=hour?trend(hour):null,z=zones(hour,quarter);show(t,z);el('context-state').textContent=(hour&&quarter?'Aktualisiert':'Daten teilweise nicht verfügbar')+' · '+stamp(Date.now());}finally{clearTimeout(timeout);if(token===generation){controller=null;timer=setTimeout(()=>load(token),60000)}}}
 function stop(){generation++;clearTimeout(timer);if(controller)controller.abort();controller=null;symbol=''}
 function open(sym,b){if(!/^[A-Z0-9]{2,40}$/.test(sym))return;stop();button=b;symbol=sym;el('context-title').textContent=sym+' · Marktüberblick';el('context-state').textContent='Marktdaten werden geladen …';show(null,null);if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');load(generation)}
 document.addEventListener('click',event=>{const b=event.target.closest('[data-context-symbol]');if(b)open(b.dataset.contextSymbol,b)});el('context-close').addEventListener('click',()=>{if(typeof dialog.close==='function')dialog.close();else{dialog.removeAttribute('open');stop();button?.focus()}});dialog.addEventListener('close',()=>{const b=button;stop();if(b?.isConnected)b.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog&&dialog.close)dialog.close()});document.addEventListener('visibilitychange',()=>{if(!symbol)return;if(document.hidden){generation++;clearTimeout(timer);controller?.abort();el('context-state').textContent='Pausiert · Dashboard nicht sichtbar'}else{generation++;load(generation)}});
 globalThis.PulseContext={parse,contiguous,ema,trend,zones};
})();
